using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Reflection;using System.Windows.Forms;using CodexWatchdog;
class MultiSelectUiTests {
 static object F(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static void Check(bool b,string m){if(!b)throw new Exception(m);}
 [STAThread]static int Main(){try{Application.EnableVisualStyles();int saves=0;var s=new WatchSettings();using(var f=new SettingsForm(s,()=>saves++,k=>{},()=>{},()=>{},()=>{})){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();Application.DoEvents();Size initialSize=f.ClientSize;var list=new List<MonitorSnapshot>{new MonitorSnapshot{SourceId="a",Title="main"},new MonitorSnapshot{SourceId="b",Title="巡查"}};f.RefreshStatus(list,"idle","",false,false,"");var c=(CheckedListBox)F(f,"targetChoices");Check(c.Items.Count==3&&c.CheckedItems.Count==3,"all default");((Button)F(f,"targets")).PerformClick();Application.DoEvents();Check(((ToolStripDropDown)F(f,"targetPopup")).Visible,"popup opens");c.SetItemChecked(2,false);Check(((ToolStripDropDown)F(f,"targetPopup")).Visible,"checking keeps popup open");((ToolStripDropDown)F(f,"targetPopup")).Close();Check(!s.MonitorAllSources&&s.SelectedSourceIds.SequenceEqual(new[]{"a"}),"direct exclusion from all keeps other choices");Check(saves==1,"single check saves once");list.Add(new MonitorSnapshot{SourceId="c",Title="new"});f.RefreshStatus(list,"idle","",false,false,"");Check(!c.GetItemChecked(3),"new discovery not opted into specific selection");c.SetItemChecked(1,false);Check(s.SelectedSourceIds.Count==0&&!s.MonitorAllSources,"individual none monitors none");c.SetItemChecked(2,true);Check(s.SelectedSourceIds.SequenceEqual(new[]{"b"}),"explicit patrol may be selected");f.RefreshStatus(new List<MonitorSnapshot>(),"idle","",false,false,"");Check(c.Items.Count==2&&c.GetItemChecked(1)&&s.SelectedSourceIds.Contains("b"),"missing selected source retained");c.SetItemChecked(0,true);Check(s.MonitorAllSources&&s.SelectedSourceIds.Count==0,"all mode auto discovery");c.SetItemChecked(0,false);Check(!s.MonitorAllSources&&s.SelectedSourceIds.Count==0&&c.CheckedItems.Count==0,"all off clears all");Check(f.ClientSize==initialSize,"main settings size unchanged at baseline DPI");f.Close();}Console.WriteLine("PASS: multiselect all/specific/none, direct exclusions, per-check saving, new-source opt-in and retained unavailable selection");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
